package com.kongye.floatball;
import android.Manifest;
import android.content.*;
import android.content.pm.PackageManager;
import android.media.*;
import android.media.projection.MediaProjection;
import android.os.*;
import android.view.Surface;
import java.io.*;
import java.nio.ByteBuffer;
import java.util.*;
import java.util.function.Consumer;

/** Worker-owned codecs and audio inputs; pause removes time from both audio and video. */
final class RecordingEngine {
    static final class Result {final File file;final String error;Result(File file,String error){this.file=file;this.error=error;}}
    private final Context context;private final MediaProjection projection;private final RecordingSpec spec;
    private volatile boolean stop,pause;private volatile long durationMs;private boolean muxing;private int videoTrack=-1,audioTrack=-1,videoSamples;private MediaMuxer muxer;private final ArrayList<Sample> queued=new ArrayList<>();private int queuedBytes;private long lastVideoUs=-1,lastAudioUs=-1;
    private static final class PcmQueue {final byte[] bytes=new byte[65536];int head,size;void clear(){head=size=0;}void add(byte[] value,int length){for(int i=0;i<length;i++){if(size==bytes.length){head=(head+2)%bytes.length;size-=2;}bytes[(head+size)%bytes.length]=value[i];size++;}}void take(byte[] output,int length){for(int i=0;i<length;i++){output[i]=bytes[head];head=(head+1)%bytes.length;}size-=length;}}
    private static final class Sample {final boolean video;final byte[] bytes;final long time;final int flags;Sample(boolean v,byte[] bytes,long time,int flags){video=v;this.bytes=bytes;this.time=time;this.flags=flags;}}
    RecordingEngine(Context c,MediaProjection projection,RecordingSpec spec){context=c;this.projection=projection;this.spec=spec;}
    void requestStop(){stop=true;}void setPaused(boolean value){pause=value;}boolean isPaused(){return pause;}long durationMs(){return durationMs;}
    private AudioRecord input(boolean playback)throws Exception{if(context.checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED)throw new IOException("声音权限未允许");int rate=44100;AudioFormat pcm=new AudioFormat.Builder().setSampleRate(rate).setEncoding(AudioFormat.ENCODING_PCM_16BIT).setChannelMask(AudioFormat.CHANNEL_IN_MONO).build();int buffer=Math.max(16384,AudioRecord.getMinBufferSize(rate,AudioFormat.CHANNEL_IN_MONO,AudioFormat.ENCODING_PCM_16BIT)*4);AudioRecord.Builder builder=new AudioRecord.Builder().setAudioFormat(pcm).setBufferSizeInBytes(buffer);if(playback&&Build.VERSION.SDK_INT>=29)builder.setAudioPlaybackCaptureConfig(new AudioPlaybackCaptureConfiguration.Builder(projection).addMatchingUsage(AudioAttributes.USAGE_MEDIA).addMatchingUsage(AudioAttributes.USAGE_GAME).addMatchingUsage(AudioAttributes.USAGE_UNKNOWN).build());else builder.setAudioSource(MediaRecorder.AudioSource.MIC);AudioRecord record=builder.build();if(record.getState()!=AudioRecord.STATE_INITIALIZED){record.release();throw new IOException("声音设备不可用");}try{record.startRecording();}catch(RuntimeException error){record.release();throw error;}if(record.getRecordingState()!=AudioRecord.RECORDSTATE_RECORDING){record.release();throw new IOException("无法启动声音录制");}return record;}
    void run(Consumer<Result> finished){MediaCodec video=null,audio=null;AudioRecord first=null,second=null;Surface surface=null;RecordingGl gl=null;File file=null;boolean success=false;String error=null;
        try{boolean sound=!spec.audio.equals("silent"),both=spec.audio.equals("both");file=RecordingFiles.create(context,"mp4");muxer=new MediaMuxer(file.getPath(),MediaMuxer.OutputFormat.MUXER_OUTPUT_MPEG_4);MediaFormat format=MediaFormat.createVideoFormat(MediaFormat.MIMETYPE_VIDEO_AVC,spec.width,spec.height);format.setInteger(MediaFormat.KEY_COLOR_FORMAT,MediaCodecInfo.CodecCapabilities.COLOR_FormatSurface);format.setInteger(MediaFormat.KEY_BIT_RATE,Math.min(8000000,Math.max(700000,spec.width*spec.height*3)));format.setInteger(MediaFormat.KEY_FRAME_RATE,spec.gif?10:30);format.setInteger(MediaFormat.KEY_I_FRAME_INTERVAL,1);video=MediaCodec.createEncoderByType(MediaFormat.MIMETYPE_VIDEO_AVC);video.configure(format,null,null,MediaCodec.CONFIGURE_FLAG_ENCODE);surface=video.createInputSurface();video.start();
            if(sound){if(context.checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED)throw new IOException("声音权限未允许");first=input(spec.audio.equals("internal")||both);if(both)second=input(false);MediaFormat aac=MediaFormat.createAudioFormat(MediaFormat.MIMETYPE_AUDIO_AAC,44100,1);aac.setInteger(MediaFormat.KEY_AAC_PROFILE,MediaCodecInfo.CodecProfileLevel.AACObjectLC);aac.setInteger(MediaFormat.KEY_BIT_RATE,128000);aac.setInteger(MediaFormat.KEY_MAX_INPUT_SIZE,8192);audio=MediaCodec.createEncoderByType(MediaFormat.MIMETYPE_AUDIO_AAC);audio.configure(aac,null,null,MediaCodec.CONFIGURE_FLAG_ENCODE);audio.start();}
            gl=new RecordingGl(projection,surface,spec);long origin=System.nanoTime()/1000,pausedAt=0,pausedUs=0,lastFrame=-1000000,audioFrames=0,stopAt=0,frozenActive=0;PcmQueue firstPcm=new PcmQueue(),secondPcm=new PcmQueue();boolean videoEnd=false,audioEnd=!sound,audioEos=!sound;byte[] pcm=new byte[4096],extra=new byte[4096],mixed=new byte[4096];MediaCodec.BufferInfo info=new MediaCodec.BufferInfo();
            while(!videoEnd||!audioEnd){long now=System.nanoTime()/1000;if(pause&&pausedAt==0)pausedAt=now;if(!pause&&pausedAt!=0){pausedUs+=now-pausedAt;pausedAt=0;}long active=Math.max(0,now-origin-pausedUs-(pausedAt==0?0:now-pausedAt));if(stopAt!=0)active=frozenActive;durationMs=active/1000;
                if(!stop&&durationMs>=(spec.gif?30000:2L*60*60*1000))stop=true;
                if(stop&&stopAt==0){stopAt=System.nanoTime();frozenActive=active;video.signalEndOfInputStream();}
                if(!stop){boolean encode=!pause&&active-lastFrame>=(spec.gif?100000:33333);if(gl.frame(active,encode))lastFrame=active;}
                if(audio!=null&&!audioEos){
                    if(!stop){int n=first.read(pcm,0,pcm.length,AudioRecord.READ_NON_BLOCKING),n2=second==null?0:second.read(extra,0,extra.length,AudioRecord.READ_NON_BLOCKING);if(n<0||n2<0)throw new IOException("声音读取中断");firstPcm.add(pcm,n);if(both)secondPcm.add(extra,n2);}
                    if(pause){firstPcm.clear();secondPcm.clear();}
                    long wanted=Math.max(0,active*44100/1000000-audioFrames);int n=(int)Math.min(pcm.length,Math.min(wanted*2,both?Math.min(firstPcm.size,secondPcm.size):firstPcm.size));n-=n%2;
                    if((!pause&&n>0)||stop){int index=audio.dequeueInputBuffer(0);if(index>=0){ByteBuffer buffer=audio.getInputBuffer(index);buffer.clear();n=Math.min(n,buffer.remaining());n-=n%2;if(n>0){firstPcm.take(pcm,n);if(both){secondPcm.take(extra,n);PcmMix.mix(pcm,n,extra,n,mixed,n);buffer.put(mixed,0,n);}else buffer.put(pcm,0,n);}boolean eos=stop&&n==0;audio.queueInputBuffer(index,0,n,audioFrames*1000000L/44100,eos?MediaCodec.BUFFER_FLAG_END_OF_STREAM:0);audioFrames+=n/2;if(eos)audioEos=true;}}
                }
                videoEnd=drain(video,true,sound,info)||videoEnd;if(audio!=null)audioEnd=drain(audio,false,sound,info)||audioEnd;if(stopAt!=0&&System.nanoTime()-stopAt>5000000000L)break;Thread.sleep(4);
            }
            if(!muxing||videoSamples<1)throw new IOException("录制时间太短，未产生有效画面");muxer.stop();muxing=false;muxer.release();muxer=null;success=true;Prefs.of(context).edit().putString("last_record_uri",file.getPath()).putString("last_record_audio",spec.audio).putInt("last_record_video_samples",videoSamples).putInt("last_record_width",spec.width).putInt("last_record_height",spec.height).putInt("last_record_crop_left",spec.crop.left).putInt("last_record_crop_top",spec.crop.top).putInt("last_record_crop_right",spec.crop.right).putInt("last_record_crop_bottom",spec.crop.bottom).putLong("last_record_active_ms",durationMs).putLong("last_record_wall_ms",Math.max(0,System.nanoTime()/1000-origin)/1000).putBoolean("last_record_private",true).apply();
        }catch(Exception|OutOfMemoryError e){error=e.getMessage()==null?"编码资源不可用":e.getMessage();}
        finally{if(gl!=null)gl.close();if(surface!=null)surface.release();for(AudioRecord record:new AudioRecord[]{first,second})if(record!=null){try{record.stop();}catch(Exception ignored){}record.release();}for(MediaCodec codec:new MediaCodec[]{video,audio})if(codec!=null){try{codec.stop();}catch(Exception ignored){}codec.release();}if(muxer!=null){try{if(muxing)muxer.stop();}catch(Exception ignored){}muxer.release();}queued.clear();if(!success&&file!=null)file.delete();}
        finished.accept(new Result(success?file:null,error));
    }
    private boolean drain(MediaCodec codec,boolean video,boolean sound,MediaCodec.BufferInfo info){boolean ended=false;for(int i=0;i<24;i++){int index=codec.dequeueOutputBuffer(info,0);if(index==MediaCodec.INFO_TRY_AGAIN_LATER)break;if(index==MediaCodec.INFO_OUTPUT_FORMAT_CHANGED){if(video)videoTrack=muxer.addTrack(codec.getOutputFormat());else audioTrack=muxer.addTrack(codec.getOutputFormat());if(!muxing&&videoTrack>=0&&(!sound||audioTrack>=0)){muxer.start();muxing=true;queued.sort(Comparator.comparingLong(s->s.time));for(Sample sample:queued)write(sample);queued.clear();queuedBytes=0;}continue;}if(index<0)continue;try{ByteBuffer data=codec.getOutputBuffer(index);if(info.size>0&&(info.flags&MediaCodec.BUFFER_FLAG_CODEC_CONFIG)==0){data.position(info.offset);data.limit(info.offset+info.size);byte[] bytes=new byte[info.size];data.get(bytes);Sample sample=new Sample(video,bytes,Math.max(0,info.presentationTimeUs),info.flags);if(muxing)write(sample);else{queuedBytes+=bytes.length;if(queuedBytes>8*1024*1024)throw new IllegalStateException("音视频轨道等待超时");queued.add(sample);}}if((info.flags&MediaCodec.BUFFER_FLAG_END_OF_STREAM)!=0)ended=true;}finally{codec.releaseOutputBuffer(index,false);}}return ended;}
    private void write(Sample s){long time=Math.max((s.video?lastVideoUs:lastAudioUs)+1,s.time);MediaCodec.BufferInfo info=new MediaCodec.BufferInfo();info.set(0,s.bytes.length,time,s.flags);muxer.writeSampleData(s.video?videoTrack:audioTrack,ByteBuffer.wrap(s.bytes),info);if(s.video){lastVideoUs=time;videoSamples++;}else lastAudioUs=time;}
}
